// The picture shown when a link to this site is shared (Open Graph image). Generated by code, one per language.
import { ImageResponse } from 'next/og';
import { getDictionary } from '@/i18n/get-dictionary';

export const alt = 'EchoSign Next';
export const size = { width: 1200, height: 630 };
export const contentType = 'image/png';

export default async function OpengraphImage({ params }) {
  const { locale } = await params;
  const d = await getDictionary(locale);
  return new ImageResponse(
    (
      <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', padding: 80, background: 'linear-gradient(135deg, #2a1a95, #5b3df5)', color: 'white' }}>
        <div style={{ fontSize: 40, opacity: 0.85 }}>{d.home.badge}</div>
        <div style={{ fontSize: 96, fontWeight: 800, marginTop: 16 }}>EchoSign Next</div>
        <div style={{ fontSize: 40, marginTop: 24, opacity: 0.9 }}>{d.home.title} {d.home.titleAccent}</div>
      </div>
    ),
    size,
  );
}
